import os
import hmac
import hashlib
import json
from flask import Flask, request, jsonify, g
import psycopg2
from psycopg2 import sql
import redis
import yaml

app = Flask(__name__)

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=os.environ.get('DB_HOST', 'localhost'),
            dbname=os.environ.get('DB_NAME', 'appdb'),
            user=os.environ.get('DB_USER', 'appuser'),
            password=os.environ.get('DB_PASS', 'secret')
        )
    return g.db

def get_cache():
    if 'cache' not in g:
        g.cache = redis.Redis(
            host=os.environ.get('REDIS_HOST', 'localhost'),
            port=int(os.environ.get('REDIS_PORT', 6379)),
            decode_responses=True
        )
    return g.cache

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def verify_session(token):
    """Verify session token against Redis store"""
    cache = get_cache()
    session_data = cache.get(f"session:{token}")
    if session_data:
        return json.loads(session_data)
    return None

@app.before_request
def auth_middleware():
    public_paths = ['/health', '/api/v1/auth/login']
    if request.path in public_paths:
        return None
    token = request.headers.get('X-Session-Token')
    if not token:
        return jsonify({"error": "unauthorized"}), 401
    session = verify_session(token)
    if not session:
        return jsonify({"error": "invalid session"}), 401
    g.user = session

@app.route('/health')
def health():
    return jsonify({"status": "ok"})

@app.route('/api/v1/reports/generate', methods=['POST'])
def generate_report():
    """Generate a report based on user-supplied template configuration"""
    user = g.user
    body = request.get_json()
    if not body or 'template' not in body:
        return jsonify({"error": "template required"}), 400

    template_name = body['template']
    # Validate template name format
    if not template_name.replace('-', '').replace('_', '').isalnum():
        return jsonify({"error": "invalid template name"}), 400

    filters = body.get('filters', {})
    date_range = filters.get('date_range', 'last_30d')
    department = filters.get('department', 'all')

    # Build report query based on filters
    db = get_db()
    cur = db.cursor()

    base_query = "SELECT id, title, amount, created_at, department FROM expenses WHERE org_id = %s"
    params = [user['org_id']]

    if department != 'all':
        base_query += " AND department = %s"
        params.append(department)

    # Custom grouping - user can specify SQL expression for grouping
    group_by = body.get('group_by', None)
    if group_by:
        # Allow common grouping expressions
        base_query += f" GROUP BY {group_by}"

    order = body.get('order_by', 'created_at DESC')
    base_query += f" ORDER BY {order}"

    limit = min(int(body.get('limit', 100)), 1000)
    base_query += f" LIMIT {limit}"

    try:
        cur.execute(base_query, params)
        rows = cur.fetchall()
    except Exception as e:
        db.rollback()
        return jsonify({"error": "query failed", "detail": str(e)}), 500

    columns = ['id', 'title', 'amount', 'created_at', 'department']
    results = [dict(zip(columns, row)) for row in rows]

    return jsonify({"report": template_name, "data": results, "count": len(results)})

@app.route('/api/v1/reports/export', methods=['POST'])
def export_report():
    """Export report to specified format with custom config"""
    body = request.get_json()
    config_yaml = body.get('export_config', '')

    # Parse YAML configuration for export settings
    try:
        config = yaml.safe_load(config_yaml)
    except yaml.YAMLError:
        return jsonify({"error": "invalid config"}), 400

    format_type = config.get('format', 'csv') if config else 'csv'
    if format_type not in ['csv', 'json', 'xlsx']:
        return jsonify({"error": "unsupported format"}), 400

    return jsonify({"status": "queued", "format": format_type})

@app.route('/api/v1/admin/config', methods=['PUT'])
def update_config():
    """Update application configuration - admin only"""
    user = g.user
    if user.get('role') != 'admin':
        return jsonify({"error": "forbidden"}), 403

    body = request.get_json()
    cache = get_cache()
    cache.set('app_config', json.dumps(body))
    return jsonify({"status": "updated"})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
